export const shuffle=<T,>(items:T[],_seed=0)=>{const out=[...items];for(let i=out.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[out[i],out[j]]=[out[j],out[i]];}return out;};
export function questionsFor(item:Lesson,language:Lang,age:Age):Question[]{
 if(age==='child')return childLessonQuestions(item,language,wordMap);
 const list=item.wordIds.map(id=>wordMap[id]).filter(Boolean);
 const out:Question[]=list.map((word,i)=>({id:`${item.id}-${i}`,type:i===2?'listen':'choice',prompt:l(`Как будет «${word.ru.toLowerCase()}» на казахском?`,`How do you say “${word.en.toLowerCase()}” in Kazakh?`,`«${word.kk}» сөзін табыңыз`),answer:word.kk,options:shuffle([word.kk,...shuffle(words.filter(w=>w.id!==word.id&&!list.some(v=>v.kk===w.kk)).map(w=>w.kk)).slice(0,2),list[(i+1)%list.length].kk].filter((v,n,a)=>a.indexOf(v)===n)),wordId:word.id,explanation:l(`${word.kk} — ${word.ru.toLowerCase()}.`,`${word.kk} means ${word.en.toLowerCase()}.`,`${word.kk} — дұрыс жауап.`)}));
 out.push({id:`${item.id}-gap`,type:'gap',prompt:l('Дополните фразу','Complete the phrase','Сөйлемді толықтырыңыз'),sentence:item.sentence.replace(item.missing,'_____'),answer:item.missing,options:[],translation:item.translation,explanation:item.translation});
 out.push({id:`${item.id}-order`,type:'order',prompt:l('Соберите предложение по переводу','Build a sentence from the translation','Сөйлемді дұрыс құраңыз'),answer:item.sentence,options:shuffle(item.sentence.replace(/[.!?]/g,'').split(' '),3),translation:item.translation,explanation:item.translation});
 if(item.level==='B1')out.push(...(item.id==='opinion'?[
  {id:'opinion-context',type:'choice' as const,prompt:l('Выберите вежливое несогласие','Choose a polite way to disagree','Сыпайы келіспеуді таңдаңыз'),answer:'Пікіріңізді түсінемін, бірақ мен басқаша ойлаймын.',options:['Пікіріңізді түсінемін, бірақ мен басқаша ойлаймын.','Менің атым Айдана.','Дүкен сағат тоғызда ашылады.'],explanation:l('«Понимаю ваше мнение, но думаю иначе» — вежливое несогласие.','“I understand your opinion, but I think differently” is a polite disagreement.','Алдымен пікірді түсінгеніңізді айтып, өз ойыңызды білдіріңіз.')},
  {id:'opinion-reason',type:'choice' as const,prompt:l('С каким словом можно объяснить причину?','Which word introduces a reason?','Себепті қай сөзбен түсіндіруге болады?'),answer:'Өйткені',options:['Өйткені','Бірақ','Немесе'],explanation:l('Өйткені — потому что. Бірақ — но. Немесе — или.','Өйткені means because. Бірақ means but. Немесе means or.','«Өйткені» сөзі себепті білдіреді.')}
 ]:[
  {id:'future-context',type:'choice' as const,prompt:l('Выберите предложение с условием','Choose the sentence with a condition','Шарт мәнді сөйлемді таңдаңыз'),answer:'Егер суды үнемдесек, табиғатқа көмектесеміз.',options:['Егер суды үнемдесек, табиғатқа көмектесеміз.','Бүгін күн жылы.','Мен су ішіп отырмын.'],explanation:l('«Если будем экономить воду, поможем природе»: егер ... -сек выражает условие.','“If we save water, we help nature”: егер ... -сек expresses a condition.','«Егер» және «-сек» шартты білдіреді.')},
  {id:'future-purpose',type:'choice' as const,prompt:l('Как сказать «Чтобы защитить природу»?','How do you say “In order to protect nature”?','Мақсатты білдіретін тіркесті таңдаңыз'),answer:'Табиғатты қорғау үшін',options:['Табиғатты қорғау үшін','Табиғат өте әдемі','Табиғат туралы кітап'],explanation:l('Үшін в этой конструкции указывает цель: для того чтобы.','Үшін marks purpose in this phrase: in order to.','«Үшін» сөзі мақсатты білдіреді.')}
 ]));
 if(list.length>=3){out.push({id:item.id+'-match',type:'match',prompt:l('Соедините слова и значения','Match words with their meanings','Сөздер мен мағыналарды сәйкестендіріңіз'),answer:'matched',options:[],pairs:list.slice(0,4).map(w=>({left:w.kk,right:l(w.ru,w.en,w.kk)})),explanation:l('Каждому слову соответствует одно значение.','Each word has one matching meaning.','Әр сөзге бір мағына сәйкес келеді.')});}
 if(list.filter(w=>!w.kk.includes(' ')).length>=3){out.push({id:item.id+'-crossword',type:'crossword',prompt:l('Заполните словесную сетку по подсказкам','Complete the crossword from the clues','Көмекке сүйеніп, сөзжұмбақты толтырыңыз'),answer:'solved',options:[],entries:list.filter(w=>!w.kk.includes(' ')).slice(0,4).map(w=>({word:w.kk,clue:l(w.ru,w.en,w.kk)})),explanation:l('Слова пересекаются на общей букве.','Words cross at a shared letter.','Сөздер ортақ әріп арқылы қиылысады.')});}
 return shuffle(age==='senior'?seniorQuestions(out,list):out);
}
